  // Sync with Live Django REST API Backend
  useEffect(() => {
    const syncDjangoData = async () => {
      try {
        const liveData = await fetchDjangoRestaurants();
        let deletedIds = [];
        try {
          const savedDel = localStorage.getItem('kanyamanan_deleted_restaurants_ids');
          if (savedDel) deletedIds = JSON.parse(savedDel) || [];
        } catch (e) { }

        if (Array.isArray(liveData) && liveData.length > 0) {
          const valid = liveData.filter(r => r && r.id && !deletedIds.includes(r.id) && !isLegacyPreseeded(r));
          if (valid.length > 0) {
            setRestaurants(prev => {
              const liveDict = {};
              valid.forEach(r => {
                if (r && r.id && !isLegacyPreseeded(r)) {
                  const pre = (PRESEEDED_RESTAURANTS || []).find(p => p && (p.id === r.id || (p.name && r.name && p.name.toLowerCase() === r.name.toLowerCase())));
                  const liveBranches = Array.isArray(r.branches) ? [...r.branches] : [];
                  if (Array.isArray(pre?.branches)) {
                    pre.branches.forEach(pb => {
                      const exists = liveBranches.some(cb =>
                        (cb.branchName && pb.branchName && cb.branchName.toLowerCase() === pb.branchName.toLowerCase()) ||
                        (cb.municipality && pb.municipality && cb.municipality.toLowerCase() === pb.municipality.toLowerCase())
                      );
                      if (!exists) {
                        liveBranches.push(pb);
                      }
                    });
                  }
                  liveDict[r.id] = {
                    ...r,
                    branches: liveBranches.length > 0 ? liveBranches : (pre?.branches || r.branches)
                  };
                }
              });
              const currentList = Array.isArray(prev) && prev.length > 0 ? prev.filter(r => r && r.id && !deletedIds.includes(r.id) && !isLegacyPreseeded(r)) : [];
              const merged = currentList.map(r => (r && r.id && liveDict[r.id]) || r).filter(r => r && !deletedIds.includes(r.id) && !isLegacyPreseeded(r));
              valid.forEach(vr => {
                if (vr && vr.id && !deletedIds.includes(vr.id) && !isLegacyPreseeded(vr) && !merged.some(m => m && (m.id === vr.id || (m.name && vr.name && m.name.toLowerCase() === vr.name.toLowerCase())))) {
                  merged.push(liveDict[vr.id] || vr);
                }
              });
              try {
                localStorage.setItem('kanyamanan_restaurants_db', JSON.stringify(merged));
              } catch (e) { }
              return merged;
            });
          }
        }
        const liveRequests = await fetchDjangoChangeRequests();
        if (Array.isArray(liveRequests) && liveRequests.length > 0) {
          const mapped = liveRequests.map(r => ({
            id: r.id || r.request_id,
            restaurantId: r.restaurantId || r.restaurant_id,
            restaurantName: r.restaurantName || r.restaurant_name,
            submittedAt: r.dateSubmitted || 'Recently',
            status: r.status || 'pending',
            original: r.details?.original || { profile: 'Original Profile' },
            changes: r.details?.changes || { profile: 'Requested updates' },
            fullUpdatedRes: r.details?.fullUpdatedRes || null,
            adminNote: r.details?.adminNote || '',
            reviewedAt: r.details?.reviewedAt || '',
            dismissedByMerchant: Boolean(r.details?.dismissedByMerchant)
          }));
          setPendingApprovals(mapped);
          try {
            localStorage.setItem('kanyamanan_pending_approvals_db', JSON.stringify(mapped));
          } catch (e) { }
        }
      } catch (err) {
        console.warn("Initial Django sync warning:", err);
      }
    };
    syncDjangoData();
  }, []);

